describe('navigateTo', () => {
  it('queues a navigation raised before the navigator mounts, and flushes it after', () => {
    const navigate = jest.fn();
    const spy = jest.spyOn(navigationRef, 'isReady').mockReturnValue(false);
    navigateTo('Somewhere', { id: 1 });
    expect(navigate).not.toHaveBeenCalled();
    spy.mockReturnValue(true);
    Object.defineProperty(navigationRef, 'navigate', { value: navigate, configurable: true });
    flushPendingNav();
    expect(navigate).toHaveBeenCalledWith('Somewhere', { id: 1 });
    // a second flush must not repeat it
    navigate.mockClear();
    flushPendingNav();
    expect(navigate).not.toHaveBeenCalled();
    spy.mockRestore();
  });
  it('navigates straight through once the navigator is ready', () => {
    const navigate = jest.fn();
    const spy = jest.spyOn(navigationRef, 'isReady').mockReturnValue(true);
    Object.defineProperty(navigationRef, 'navigate', { value: navigate, configurable: true });
    navigateTo('Direct');
    expect(navigate).toHaveBeenCalledWith('Direct', undefined);
    spy.mockRestore();
  });
});

