describe('i18n', () => {
  it('declares its locales and which of them are right-to-left', () => {
    expect(LOCALES.length).toBeGreaterThan(0);
    expect(LOCALES).toContain('en');
    for (const l of RTL_LOCALES) expect(isRTLLocale(l)).toBe(true);
    expect(isRTLLocale('en')).toBe(false);
  });
  it('falls back to the key itself rather than rendering blank', () => {
    expect(t('definitely.not.a.key')).toBe('definitely.not.a.key');
  });
  it('exposes t and the current locale through the provider', () => {
    let seen: ReturnType<typeof useI18n> | null = null;
    const Probe = () => { seen = useI18n(); return <Text>probe</Text>; };
    let tree!: renderer.ReactTestRenderer;
    act(() => { tree = renderer.create(<I18nProvider><Probe /></I18nProvider>); });
    expect(typeof seen!.t).toBe('function');
    expect(LOCALES).toContain(seen!.locale);
    act(() => tree.unmount());
  });
});

describe('theme', () => {
  it('cycles the mode through the provider and keeps the choice', () => {
    let ctx: ReturnType<typeof useThemeMode> | null = null;
    const Probe = () => { ctx = useThemeMode(); return <Text>probe</Text>; };
    let tree!: renderer.ReactTestRenderer;
    act(() => { tree = renderer.create(<ThemeProvider><Probe /></ThemeProvider>); });
    expect(['light', 'dark', 'system']).toContain(ctx!.mode);
    act(() => ctx!.setMode('dark'));
    expect(ctx!.mode).toBe('dark');
    act(() => ctx!.setMode('light'));
    expect(ctx!.mode).toBe('light');
    act(() => ctx!.setMode('system'));
    expect(ctx!.mode).toBe('system');
    act(() => tree.unmount());
  });
  it('font() answers for an unregistered family without throwing', () => {
    // expo answers undefined (nothing to load); the rncli target answers with the
    // family name itself, because there the name IS the platform font
    const out = font('NotARealFamily', '400');
    expect(out === undefined || typeof out === 'string').toBe(true);
  });
});
